function keepInView(name) {
  try {
    var b = document.querySelector('.nav-btn[data-tab="' + name + '"]');
    if (b && b.scrollIntoView) b.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  } catch (e) {}
}

patches.replace:
function keepInView(name) {
  try {
    var b = document.querySelector('.nav-btn[data-tab="' + name + '"]');
    if (!b || !b.scrollIntoView) return;
    // If it is already fully in view, leave the strip where it is - scrolling
    // anyway shoves the tabs before it off the left edge for no reason.
    var n = b.closest('nav'), r = b.getBoundingClientRect();
    var nr = n ? n.getBoundingClientRect() : null;
    if (nr && r.left >= nr.left - 1 && r.right <= nr.right + 1) return;
    b.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  } catch (e) {}
}

#nav-profile,#btn-clear-all,#hdr-props{display:none!important}
/* The wordmark stays, the strapline and the rule go, and the header stops
   padding 24px into a 390px screen. That is ~130px back for the tabs -
   the difference between one tab visible and five. */
#hdr{padding:0 8px!important;gap:8px!important}
#hdr-brand{padding:10px 0 8px!important}
#hdr-word{font-size:15px!important}
#hdr-strap,#hdr-rule{display:none!important}
